{"_table": "def", "entry_id": 10716, "idx": 0, "text": "الواعظ"}
{"_table": "def", "entry_id": 10716, "idx": 1, "text": "هادى السفن فى المضايق"}
{"_table": "def", "entry_id": 10716, "idx": 2, "text": "دليل الشرطة"}
{"_table": "def", "entry_id": 15547, "idx": 0, "text": "العليم الذي يؤخذ رأيه في أمر هام علميّ أو فنيّ أو سياسي أو قضائي أو نحوه"}
{"_table": "def", "entry_id": 29316, "idx": 0, "text": "الخالص من كلِّ شيء"}
{"_table": "def", "entry_id": 29316, "idx": 1, "text": "يقال: سقانى ناصح الشَّراب"}
{"_table": "def", "entry_id": 29316, "idx": 2, "text": "يقال: ناصح الجيب: نقى القلب لا غش فيه"}
{"_table": "def", "entry_id": 29316, "idx": 3, "text": "الخيَّاط"}
{"_table": "def", "entry_id": 29322, "idx": 0, "text": "النَّاصِح"}
{"_table": "def", "entry_id": 53847, "idx": 0, "text": "دَرَجَةٌ وظيفِيَّةٌ عاليةٌ فى بعضِ مؤسساتِ الدولةِ. يقال: مستشارٌ قانونىٌّ, ومستشارٌ ثقافى"}
{"_table": "def", "entry_id": 53847, "idx": 1, "text": "رتبةٌ قضائيَّةٌ في المحاكم وغيرها. يقال: مستشارٌ بِمَجْلس الدَّولةِ"}
{"_table": "def", "entry_id": 53847, "idx": 2, "text": "لَقَبٌ يُطلقُ على رئيس الحكومةِ فى بعض الدول كألمانيا والنمسا"}
{"_table": "def", "entry_id": 53856, "idx": 0, "text": "أعلى رتبةٍ عَسْكَرِيَّةٍ فى الجيشِ, وهى فوقَ رتبة الفريق أوَّل"}
{"_table": "def", "entry_id": 93734, "idx": 0, "text": "الواعِظُ, وقيل: الهادِي"}
{"_table": "def", "entry_id": 93734, "idx": 1, "text": "هادِى السُّفُن في المَضَايِق"}
{"_table": "def", "entry_id": 93734, "idx": 2, "text": "دَلِيلُ الشُّرْطَةِ إلى الخارجين على القانون"}
{"_table": "def", "entry_id": 93734, "idx": 3, "text": "(عند الصُّوفِيَّة): الشيخُ المربِّي"}
{"_table": "def", "entry_id": 93734, "idx": 4, "text": "المُرْشِد السياحيُّ: من يَصحَب السَّيَّاح فى زيارتهم للآثار؛ ليشرحَ لهم تاريخَها ومكانتها"}
{"_table": "ex", "entry_id": 93734, "idx": 0, "text": "وَمَن يُضْلِلْ فَلَن تَجِدَ لَهُ وَلِيًّا مُّرْشِدًا", "type": "quran"}
{"_table": "def", "entry_id": 882739, "idx": 0, "text": "(المرشد) الْوَاعِظ وهادي السفن فِي المضايق وَدَلِيل الشرطة (محدثة)"}
{"_table": "def", "entry_id": 883042, "idx": 0, "text": "(المستشار) الْعَلِيم الَّذِي يُؤْخَذ رَأْيه فِي أَمر هام علمي أَو فني أَو سياسي أَو قضائي أَو نَحوه (محدثة)"}
{"_table": "def", "entry_id": 885382, "idx": 0, "text": "(الناصح) الْخَالِص من كل شَيْء يُقَال سقاني نَاصح الشَّرَاب وَيُقَال نَاصح الجيب نقي الْقلب لَا غش فِيهِ والخياط"}
{"_table": "def", "entry_id": 885899, "idx": 0, "text": "(النصيح) الناصح (ج) نصحاء"}
{"_table": "def", "entry_id": 944289, "idx": 0, "text": "مُسْتَشَار\nمن (ش و ر) من تطلب نصيحته وآراؤه."}
{"_table": "def", "entry_id": 944750, "idx": 0, "text": "مُشِير\nمن (ش و ر) من يومئ بيده أو نحوها إلى غيره معبرا عن معنى من المعاني والناصح غيره بفعل أمرما، والمشير: أعلى رتبه عسكرية."}
{"_table": "def", "entry_id": 947256, "idx": 0, "text": "نَاصِح\nمن (ن ص ح) المرشد إلى ما فيه الصلاح، والشارب حتى يروي، والخالص من كل شيء والخياط."}
TOTAL: 26

